using Microsoft.EntityFrameworkCore;

// Cosmos DB context demonstrating EF Core 9 breaking-change fixes.
class CosmosContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
        => options.UseCosmos(
            "https://localhost:8081",
            "C2y6yDjf5/R+ob0N8A7Cgv30VRDJIWEHLM+4QDU5DE2nQ9nDuVTqobD4b8mGGyPMbIZnqyMsEcaGQy67XIw/Jw==",
            "CatalogDb");

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: the default discriminator property name
        // changed from "Discriminator" to "$type". Existing documents already
        // store "Discriminator", so we must keep the old name explicitly.
        modelBuilder.Entity<Product>()
            .HasDiscriminator<string>("Discriminator");
    }
}

// Example: all Cosmos queries must be async in EF Core 9.
// Synchronous calls (ToList, First, Count, etc.) now throw
// InvalidOperationException.
class ProductService
{
    private readonly CosmosContext _db;
    public ProductService(CosmosContext db) => _db = db;

    // BEFORE (EF Core 8 – worked but was blocking):
    //   var list = _db.Products.Where(p => p.Price > 0).ToList();
    //   var first = _db.Products.First();
    //   var count = _db.Products.Count();
    //
    // AFTER (EF Core 9 – must use async):
    public async Task<List<Product>> GetAllAsync()
        => await _db.Products.Where(p => p.Price > 0).ToListAsync();

    public async Task<Product> GetFirstAsync()
        => await _db.Products.FirstAsync();

    public async Task<int> CountAsync()
        => await _db.Products.CountAsync();
}

class Product
{
    public string Id { get; set; } = null!;
    public string Name { get; set; } = null!;
    public decimal Price { get; set; }
}

